'use strict';
const $ = id => document.getElementById(id);
let schools = [], selected = new Set(), expanded = new Set();
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = url => { try { const u = new URL(url); return u.protocol === 'https:' ? esc(u.href) : '#'; } catch { return '#'; } };
const statusLabels = {verified:'School source',tentative:'Unconfirmed',unknown:'Not verified',external:'Niche source'};
function evidence(f){return `<div class="evidence"><span class="badge ${esc(f.status)}">${statusLabels[f.status] || 'Needs checking'}</span>${f.url ? ` <a href="${safeUrl(f.url)}" target="_blank" rel="noopener noreferrer">${['verified','external'].includes(f.status) ? 'Source' : 'Check school'} ↗</a>` : ''}</div>`;}
function detailContent(f){return Array.isArray(f.items)?`<ul class="dateitems">${f.items.map(item=>`<li><strong>${esc(item.date)}</strong> — ${esc(item.detail)}</li>`).join('')}</ul>${f.detailNote?`<p class="detailnote">${esc(f.detailNote)}</p>`:''}`:`<p>${esc(f.text)}</p>`;}
function field(title,f){return `<div class="field"><h3>${esc(title)}</h3>${detailContent(f)}${evidence(f)}${f.checked?`<small class="ratingchecked">Checked ${esc(f.checked)}${f.status==='external'?' · Niche grade, not review stars.':''}</small>`:''}</div>`;}
function locationGroup(s){return s.state==='NJ'?(s.city==='Jersey City'?'jersey-city':'nj-other'):'nyc';}
function locationRank(s){return ['jersey-city','nj-other','nyc'].indexOf(locationGroup(s));}
function filtered(){const q=$('search').value.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');return schools.filter(s=>(!$('location').value||locationGroup(s)===$('location').value)&&(!$('type').value||s.type===$('type').value)&&(!$('gender').value||s.gender===$('gender').value)&&JSON.stringify(s).toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q)).sort((a,b)=>{const k=$('sort').value;if(k==='local')return locationRank(a)-locationRank(b)||a.name.localeCompare(b.name);if(k==='niche')return nicheRank(a)-nicheRank(b)||a.name.localeCompare(b.name);if(k==='tuition')return (a.tuition.amount??Infinity)-(b.tuition.amount??Infinity)||a.name.localeCompare(b.name);if(k==='deadline')return nextDeadline(a).localeCompare(nextDeadline(b))||a.name.localeCompare(b.name);if(k==='city')return a.city.localeCompare(b.city)||a.name.localeCompare(b.name);return a.name.localeCompare(b.name);});}
function nicheRank(s){const grades=['A+','A','A-','B+','B','B-','C+','C','C-','D+','D','D-','F'];const rank=grades.indexOf(s.niche?.grade);return rank<0?Infinity:rank;}
function nextDeadline(s){const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/New_York'});return (s.deadline.dates||[]).filter(d=>d>=today).sort()[0]||'9999-12-31';}
function selectionLabel(){ $('compare').textContent=`Compare selected (${selected.size})`;$('compare').disabled=selected.size<2; }
const detailSections=[['Niche rating','niche'],['Open house & visits','visits'],['Application deadlines','deadline'],['Entrance exam','exam'],['Tuition & fees','tuition'],['Admission process','admissions'],['Extracurriculars','activities'],['College records','college']];
function compact(s,key){
 const f=s[key];
 if(key==='niche')return `<a class="nichegrade ${f.grade?'':'unrated'}" href="${safeUrl(f.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(s.name)}: ${f.grade?'Niche overall grade '+esc(f.grade):'not rated on Niche'}">${esc(f.grade || 'Not rated')}</a><small>Overall grade</small>`;
 if(key==='tuition')return `<span class="amount">${f.amount===null?'Not verified':f.amount===0?'Tuition-free':'$'+f.amount.toLocaleString('en-US')}</span>${f.year?`<small>${esc(f.year)}</small>`:'<small>Check eligibility / fees</small>'}`;
 const label=f.summary || (f.status==='unknown'?'Not verified':'View details');
 return `<span>${esc(label)}</span>${f.note?`<small>${esc(f.note)}</small>`:''}${f.status==='tentative'?'<small class="tentative">Unconfirmed</small>':f.status==='unknown'&&label!=='Not verified'&&!label.startsWith('Check')?'<small>Not verified</small>':''}`;
}
function toggleSchool(id){
 if(!schools.some(s=>s.id===id))return;
 expanded.has(id)?expanded.delete(id):expanded.add(id);
 render();
 $('toggle-'+id)?.focus({preventScroll:true});
}
function render(){
 const rows=filtered();
 $('count').textContent=`${rows.length} of ${schools.length} schools`;
 const columns=[['Niche','niche'],['Open house','visits'],['Apply by','deadline'],['Entrance exam','exam'],['Annual tuition','tuition'],['College records','college']];
 $('results').innerHTML=rows.length?`<table class="schooltable"><caption class="sr-only">Schools at a glance. Expand a school for all details.</caption><thead><tr><th scope="col">School</th>${columns.map(([title])=>`<th scope="col">${title}</th>`).join('')}</tr></thead><tbody>${rows.map(s=>`<tr class="schoolrow ${expanded.has(s.id)?'is-open':''}" data-school="${esc(s.id)}"><th scope="row"><div class="schoolidentity"><button id="toggle-${esc(s.id)}" class="expand" data-expand="${esc(s.id)}" aria-expanded="${expanded.has(s.id)}" aria-controls="details-${esc(s.id)}" aria-label="${expanded.has(s.id)?'Collapse':'Expand'} ${esc(s.name)}"><span aria-hidden="true">${expanded.has(s.id)?'−':'+'}</span></button><div><button class="schoolname" data-expand="${esc(s.id)}">${esc(s.name)}</button><span class="schooltype">${esc(s.city.split(' · ')[0])}, ${esc(s.state)} · ${esc(s.gender)}</span><label class="pick"><input type="checkbox" data-id="${esc(s.id)}" ${selected.has(s.id)?'checked':''} aria-label="Compare ${esc(s.name)}">${esc(s.type)} · Compare</label></div></div></th>${columns.map(([,key])=>`<td>${compact(s,key)}</td>`).join('')}</tr><tr class="detailrow" id="details-${esc(s.id)}" ${expanded.has(s.id)?'':'hidden'}><td colspan="7"><div class="rowdetailinner"><div class="detailheading"><span>${esc(s.city)}, ${esc(s.state)} · ${esc(s.gender)}</span><a href="${safeUrl(s.website)}" target="_blank" rel="noopener noreferrer">School website ↗</a></div><div class="detailsgrid">${detailSections.map(([title,key])=>field(title,s[key])).join('')}</div><p class="reviewed">Reviewed ${esc(s.reviewed)}</p></div></td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h2>No schools match these filters.</h2><p>Try another search or reset the filters.</p></div>';
 selectionLabel();
}
function compare(){setTab('schools');const rows=schools.filter(s=>selected.has(s.id));if(rows.length<2)return;const keys=[['Niche overall grade','niche'],['Location',null],['Admission process','admissions'],['Open house / visits','visits'],['Exam & timing','exam'],['Application deadline','deadline'],['Annual tuition & fees','tuition'],['Extracurriculars','activities'],['College records','college']];$('comparisonTable').innerHTML=`<table><caption class="sr-only">Selected school comparison</caption><thead><tr><th scope="col">Details</th>${rows.map(s=>`<th scope="col">${esc(s.name)}<br><small>${esc(s.type)} · ${esc(s.gender)}</small></th>`).join('')}</tr></thead><tbody>${keys.map(([label,key])=>`<tr><th scope="row">${label}</th>${rows.map(s=>`<td>${key?`${detailContent(s[key])}${evidence(s[key])}`:esc(s.city+', '+s.state)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;$('results').hidden=true;$('results').style.display='none';$('comparison').hidden=false;$('comparison').focus();}
function closeCompare(){ $('comparison').hidden=true;$('results').hidden=false;$('results').style.display=''; }
['search','location','type','gender','sort'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',()=>{closeCompare();render();}));
$('reset').addEventListener('click',()=>{['search','location','type','gender'].forEach(id=>$(id).value='');$('sort').value='local';closeCompare();render();});
$('results').addEventListener('click',e=>{const button=e.target.closest('[data-expand]');if(button){toggleSchool(button.dataset.expand);return;}if(e.target.closest('a,input,label,button'))return;const row=e.target.closest('[data-school]');if(row)toggleSchool(row.dataset.school);});
$('results').addEventListener('change',e=>{const id=e.target.dataset.id;if(!id)return;if(e.target.checked){if(selected.size===4){e.target.checked=false;$('count').textContent='You can compare up to 4 schools. Uncheck a school to select another.';return;}selected.add(id);}else selected.delete(id);selectionLabel();});
$('compare').addEventListener('click',compare);$('closecompare').addEventListener('click',()=>{closeCompare();$('compare').focus();});
let examCatalog=[], plannerEvents=[], completedTasks=new Set(), storageAvailable=true;
const progressKey='jersey-city-high-schools:2027:completed';
const todayISO=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/New_York'});
function readProgress(){try{const saved=JSON.parse(localStorage.getItem(progressKey)||'[]');completedTasks=new Set(Array.isArray(saved)?saved.filter(x=>typeof x==='string'):[]);}catch{storageAvailable=false;completedTasks=new Set();}}
function setTaskDone(id,done){if(!plannerEvents.some(e=>e.id===id))return;done?completedTasks.add(id):completedTasks.delete(id);try{localStorage.setItem(progressKey,JSON.stringify([...completedTasks]));}catch{storageAvailable=false;}renderDates();($('task-'+id)||$('date-view')).focus({preventScroll:true});}
function setTab(name){if(!['schools','dates','exams'].includes(name))return;for(const key of ['schools','dates','exams']){$('panel-'+key).hidden=key!==name;$('tab-'+key).setAttribute('aria-selected',String(key===name));$('tab-'+key).tabIndex=key===name?0:-1;}if(name==='dates')renderDates();if(name==='exams')renderExams();}
function collectEvents(data){const collected=[];
 for(const s of data.schools){for(const key of ['visits','deadline'])for(const item of s[key].items||[]){if(s.id==='seton-hall'&&item.kind==='Exam')continue;collected.push({...item,schoolIds:[s.id],url:s[key].url,context:s[key].detailNote||'',origin:key});}for(const item of s.exam.milestones||[])collected.push({...item,schoolIds:[s.id],url:s.exam.url,context:'School-specific score or testing deadline',origin:'exam'});}
 for(const exam of data.exams||[]){const ids=data.schools.filter(s=>s.exam.examIds?.includes(exam.id)).map(s=>s.id);for(const item of exam.events)collected.push({...item,schoolIds:ids,url:exam.sourceUrl,context:exam.notes,examName:exam.name,origin:'exam'});}
 // Shared district deadlines appear once for their schools, not once per school.
 const merged=new Map();for(const event of collected){const key=[event.url,event.isoDate,event.date,event.detail,event.kind].join('|');if(merged.has(key)){const existing=merged.get(key);existing.schoolIds=[...new Set([...existing.schoolIds,...event.schoolIds])];}else merged.set(key,event);}
 return [...merged.values()].sort((a,b)=>(a.isoDate||'9999').localeCompare(b.isoDate||'9999')||a.detail.localeCompare(b.detail));
}
function schoolNames(ids){return ids.map(id=>schools.find(s=>s.id===id)?.name).filter(Boolean).join(' · ');}
function visibleEvents(){const mode=$('date-view').value,school=$('date-school').value,kind=$('date-kind').value,today=todayISO();return plannerEvents.filter(e=>(!school||e.schoolIds.includes(school))&&(!kind||e.kind===kind)&&(mode==='completed'?completedTasks.has(e.id):mode==='upcoming'?!completedTasks.has(e.id)&&(!e.isoDate||e.isoDate>=today):true));}
function renderDates(){const rows=visibleEvents();const groups=new Map();for(const e of rows){const key=e.isoDate||'unscheduled';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e);}
 $('progress-note').textContent=storageAvailable?'Checkmarks saved in this browser only. They won’t transfer to GitHub or another device.':'Browser storage is unavailable. Checkmarks will be lost when you reload.';
 const earlier=plannerEvents.filter(e=>e.isoDate&&e.isoDate<todayISO()&&!completedTasks.has(e.id)&&(!$('date-school').value||e.schoolIds.includes($('date-school').value))&&(!$('date-kind').value||e.kind===$('date-kind').value)).length;
 $('date-count').textContent=`${rows.length} items${$('date-view').value==='upcoming'&&earlier?` · ${earlier} earlier unchecked items in All`:''}`;
 $('date-results').innerHTML=rows.length?[...groups.entries()].map(([date,events])=>`<section class="dategroup"><h2>${date==='unscheduled'?'Flexible dates & dates to confirm':esc(new Date(date+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'}))}</h2><ul class="tasklist">${events.map(e=>`<li class="task ${completedTasks.has(e.id)?'taskdone':''}"><label class="taskcheck"><input type="checkbox" id="task-${esc(e.id)}" data-task="${esc(e.id)}" ${completedTasks.has(e.id)?'checked':''} aria-label="Done: ${esc(e.detail)} (${esc(e.date)})"><span class="sr-only">Done</span></label><div class="taskbody"><div class="taskmeta">${esc(e.kind)}${e.isoDate&&e.isoDate<todayISO()?' · Past date':''}${e.status!=='verified'?' · Unconfirmed':''}</div><strong>${e.isoDate?'':esc(e.date)+' — '}${esc(e.detail)}</strong><p>${esc(e.examName||schoolNames(e.schoolIds))}</p><details><summary>Details & source</summary>${e.examName?`<p>${esc(schoolNames(e.schoolIds))}</p>`:''}${e.context?`<p>${esc(e.context)}</p>`:''}<a href="${safeUrl(e.url)}" target="_blank" rel="noopener noreferrer">Official source ↗</a></details></div></li>`).join('')}</ul></section>`).join(''):'<p class="empty">No items in this view.</p>';
}
function renderExams(){const schoolId=$('exam-school').value;const exams=examCatalog.filter(ex=>!schoolId||schools.find(s=>s.id===schoolId)?.exam.examIds?.includes(ex.id));
 $('exam-count').textContent=`${exams.length} exams / assessments`;
 $('exam-results').innerHTML=exams.map(ex=>{const related=schools.filter(s=>s.exam.examIds?.includes(ex.id)&&(!schoolId||s.id===schoolId));const schedule=ex.events.map(e=>`<li><strong>${esc(e.date)}</strong> — ${esc(e.detail)}</li>`).join('');
 const prerequisites=plannerEvents.filter(e=>e.schoolIds.some(id=>related.some(s=>s.id===id))&&e.origin==='deadline'&&['Exam registration','Exam payment'].includes(e.kind));
 return `<section class="examsection"><div class="examheading"><h2>${esc(ex.name)}</h2><a class="registerlink" href="${safeUrl(ex.registrationUrl)}" target="_blank" rel="noopener noreferrer">${['isee','ssat','hspt'].includes(ex.id)?'Registration':'Booking instructions'} ↗</a></div><p>${esc(ex.registration)}</p><ul class="dateitems">${schedule}${prerequisites.map(e=>`<li><strong>${esc(e.date)}</strong> — ${esc(e.detail)}</li>`).join('')}</ul><p class="detailnote">${esc(ex.notes)}</p><details class="examrequirements"><summary>Schools & score deadlines (${related.length})</summary><div class="examtablewrap"><table class="examtable"><thead><tr><th scope="col">School</th><th scope="col">Requirement</th><th scope="col">Timing / scores</th></tr></thead><tbody>${related.map(s=>`<tr><th scope="row"><a href="${safeUrl(s.exam.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a></th><td>${esc(s.exam.requirement)}</td><td>${esc(s.exam.text)}</td></tr>`).join('')}</tbody></table></div></details><small>Checked ${esc(ex.checked)} · <a href="${safeUrl(ex.sourceUrl)}" target="_blank" rel="noopener noreferrer">Official source ↗</a></small></section>`;}).join('');
 const noExam=schools.filter(s=>(!schoolId||s.id===schoolId)&&!s.exam.examIds?.length);if(noExam.length)$('exam-results').innerHTML+=`<section class="examsection"><h2>No listed entrance exam / policy to confirm</h2>${noExam.map(s=>`<p><strong>${esc(s.name)}</strong> — ${esc(s.exam.text)} <a href="${safeUrl(s.exam.url)}" target="_blank" rel="noopener noreferrer">Source ↗</a></p>`).join('')}</section>`;
}
function initPlanner(data){examCatalog=data.exams||[];plannerEvents=collectEvents(data);readProgress();const options='<option value="">All schools</option>'+[...schools].sort((a,b)=>locationRank(a)-locationRank(b)||a.name.localeCompare(b.name)).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');$('date-school').innerHTML=options;$('exam-school').innerHTML=options;$('date-kind').innerHTML='<option value="">All actions</option>'+[...new Set(plannerEvents.map(e=>e.kind))].sort().map(kind=>`<option>${esc(kind)}</option>`).join('');renderDates();renderExams();}
for(const name of ['schools','dates','exams']){$('tab-'+name).addEventListener('click',()=>setTab(name));$('tab-'+name).addEventListener('keydown',e=>{const tabs=['schools','dates','exams'];let idx=tabs.indexOf(name);if(e.key==='ArrowRight')idx=(idx+1)%3;else if(e.key==='ArrowLeft')idx=(idx+2)%3;else if(e.key==='Home')idx=0;else if(e.key==='End')idx=2;else return;e.preventDefault();setTab(tabs[idx]);$('tab-'+tabs[idx]).focus();});}
for(const id of ['date-view','date-school','date-kind'])$(id).addEventListener('change',renderDates);
$('exam-school').addEventListener('change',renderExams);
$('date-results').addEventListener('change',e=>{if(e.target.dataset.task)setTaskDone(e.target.dataset.task,e.target.checked);});

fetch('./schools.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json();}).then(data=>{schools=data.schools;render();initPlanner(data);}).catch(()=>{$('count').textContent='School data could not load.';$('date-count').textContent='Data could not load. Please reload.';$('exam-count').textContent='Data could not load. Please reload.';$('results').innerHTML='<div class="empty"><p>Please reload this page. If you opened a downloaded copy, serve the folder with a local web server or GitHub Pages.</p><button onclick="location.reload()">Reload</button></div>';});
if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  try{Promise.resolve(document.modelContext.registerTool({name:'compare_schools',title:'Compare schools',description:'Select two to four school IDs and display their side-by-side comparison. This only changes this page.',inputSchema:{type:'object',properties:{schoolIds:{type:'array',items:{type:'string'},minItems:2,maxItems:4,uniqueItems:true}},required:['schoolIds'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){const ids=input?.schoolIds;if(!Array.isArray(ids)||ids.length<2||ids.length>4||new Set(ids).size!==ids.length||ids.some(id=>typeof id!=='string'||!schools.some(s=>s.id===id)))throw new Error('Provide two to four distinct IDs from the loaded school data.');selected=new Set(ids);render();compare();return {compared:schools.filter(s=>selected.has(s.id)).map(s=>({id:s.id,name:s.name}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}
}
